from solution import solve
import itertools

def check(xs, r):
    cnt = sum(1 for x in xs if x > r)
    return cnt == r and all(r > x for x in xs)

# exhaustive small tests
for n in range(0, 4):
    for xs in itertools.product([-3,-2,-1,0,1,2], repeat=n):
        xs = list(xs)
        r = solve(xs)
        if check(xs, r):
            pass
        else:
            # find if any valid r exists
            valid = [r2 for r2 in range(-10,10) if check(xs, r2)]
            print('FAIL', xs, 'got', r, 'valid', valid)
            break
    else:
        continue
    break
print('done')
print(solve([]), solve([-1,-2]), solve([-5]))
